/**
 * @typedef {import('lit-html').TemplateResult} TemplateResult
 * @typedef {{ value: string, label: string }} SelectOption
 * @typedef {{ label: string|null, options: SelectOption[] }} SelectGroup
 * @typedef {{
 *   key: string,
 *   groups: SelectGroup[],
 *   selected: string,
 *   disabled: boolean,
 *   runner: string|null
 * }} ExecRow
 */

